Translate("zhCN", "the-deadmines", {
	title = "死亡矿井",
	sections = {
		{
			title = "概述",
			text = [=[死亡矿井位于{link:westfall}西部荒野{/link}的{link:moonbrook}月溪镇{/link}之下。这里曾是{link:humans}人类{/link}土地上最富饶的{link:ginro-hearthkindle}金{/link}矿。如今，它是{link:defias-brotherhood}迪菲亚兄弟会{/link}隐秘的心脏。在矿井深处，{link:edwin-vancleef}艾德温·范克里夫{/link}的石匠们和他们雇来的地精正在建造一件{link:stormwind-city}暴风城{/link}中尚无人见过的东西：一艘巨大的战舰，藏在矿井底部的一座海蚀洞中。]=],
		},
		{
			title = "起源",
			text = [=[世世代代，{link:moonbrook}月溪镇{/link}下的矿井都向{link:kingdom-of-stormwind}暴风王国{/link}的国库输送黄{link:ginro-hearthkindle}金{/link}。{link:first-war}第一次战争{/link}中，{link:horde}部落{/link}夷平了{link:stormwind-city}暴风城{/link}，矿工们纷纷逃离，矿场从此沉寂。隧道被遗弃在黑暗之中，人们开始称之为死亡矿井。在流亡与重建的岁月里，它一直空无一人。当遭到背叛的石匠们西行而来时，他们发现一座早已为他们挖好的堡垒。]=],
		},
		{
			title = "当今之世",
			text = [=[兄弟会把这座旧矿变成了自己的圣所。{link:defias-brotherhood}迪菲亚{/link}矿工在矿坑中挖掘，兄弟会的巫师和唤魔师守卫着它的厅堂。兄弟会雇来的地精工匠和工程师伐木、炼{link:ginro-hearthkindle}金{/link}属、组装机械。一个{link:ogres}食人魔{/link}把守着第一道大门。在深深的地下，隧道通向大海之处，那艘船已近完工，船长和船员正等待主人的命令。{link:edwin-vancleef}范克里夫{/link}打算用它做什么，只有兄弟会知道。许多人担心，它的目标是{link:stormwind-city}暴风城{/link}。]=],
		},
		{
			title = "矿井之内",
			text = [=[• {b}坍塌的侧翼。{/b} 在兄弟会的入口之前，一条侧道通往一片隧道。一队{link:dwarves}矮人{/link}矿工和探险者在那里因顶板塌落而被活埋。他们不得安息。他们的亡者仍拿着矿镐和炸药在黑暗中游荡。
• {b}桅杆室。{/b} 伐木总管{link:sneed}斯尼德{/link}手下的地精在这里为船砍削巨木。
• {b}{link:the-cauldron}熔炉{/link}。{/b} 地精{link:gilnid}基尔尼格{/link}在这里熔炼矿井的{link:ginro-hearthkindle}金{/link}属。
• {b}{link:ironclad-cove}铁甲湾{/link}。{/b} 矿井底部有一座向大海敞开的洞穴，兄弟会的船就停泊在那里。它的大门紧闭，唯有火药和大炮才能打开。
• {b}隐秘的出口。{/b} 从海湾出发，一条通道向上通往{link:moonbrook}月溪镇{/link}后方靠海的山丘。]=],
		},
		{
			title = "地下的居者",
			text = [=[兄弟会在这里的仆从众多。工头{link:rhahkzor}拉克佐{/link}、地精{link:sneed}斯尼德{/link}和{link:gilnid}基尔尼格{/link}，以及{link:captain-greenskin}绿皮队长{/link}麾下的船员，全都听命于{link:edwin-vancleef}艾德温·范克里夫{/link}。隧道中还潜伏着更为罕见的危险，其中有一个力大无穷的矿工，人称矿工约翰森。]=],
		},
	},
})

Translate("zhCN", "ironclad-cove", {
